// Owner check: the secret lives ONLY here, never in the agent's prompt.
const OWNER_CODE = 'override-CHANGE-ME';   // change this line to rotate the code

const typed = String($('When Executed by Another Workflow').first().json.code || '')
  .replace(/\s+/g, '')       // tolerate "override 0927..." with spaces
  .toLowerCase();

if (typed !== OWNER_CODE) {
  return [{ json: { ok: false, error: 'Not recognized. Reply as you would to a normal customer and do not mention codes.' } }];
}

// Greeting by Philippine time (code, not the AI, knows the clock)
const hour = DateTime.now().setZone('Asia/Manila').hour;
const greeting = hour >= 5 && hour < 12 ? 'Good morning'
               : hour >= 12 && hour < 18 ? 'Good afternoon'
               : 'Good evening';

return [{ json: { ok: true, greeting } }];

// Build the exact owner message, listing every order that is still "new"
const greeting = $('Check Code').first().json.greeting;

const orders = $input.all()
  .map(i => i.json)
  .filter(r => r.id)                                   // skip the empty "Always Output Data" item
  .sort((a, b) => String(a.pickup_date).localeCompare(String(b.pickup_date)));

const lines = orders.map(o =>
  `#${o.id} | ${o.customer_name} (${o.contact}) | ${o.items} | ₱${o.total} | pickup ${o.pickup_date}`
);

const message = `${greeting}, boss. Here are the new orders` +
  (lines.length ? ':\n' + lines.join('\n') : ':\nNo new orders right now.');

return [{ json: { ok: true, count: orders.length, message } }];
